-- c028-v001: Dan diselamatkan, kemudian mengetahui bahwa Melitē – pulau disebut.
-- c028-v002: – Dan penduduk–asli memberikan tidak – biasa kebaikan kita; menyalakan karena api, menerima semua kita, karena – hujan – yang–ada, dan karena – dingin.
-- c028-v003: Mengumpulkan dan – Paulos ranting beberapa banyak, dan menaruh di–atas – api, ular–berbisa dari – panas keluar, menggigit – tangan –nya.
-- c028-v004: Ketika dan, melihat – penduduk–asli menggantung – binatang dari – tangan –nya, kepada satu–sama–lain berkata, Tentu pembunuh adalah – manusia ini, yang diselamatkan dari – laut, – Keadilan hidup tidak membiarkan.
-- c028-v005: – Memang maka, mengibaskan – binatang ke – api, menderita tidak–ada jahat.
-- c028-v006: – Dan mengharapkan dia akan membengkak, atau jatuh tiba-tiba mati. Untuk lama dan, mereka mengharapkan dan melihat tidak–ada aneh kepada dia terjadi, berubah, berkata dia adalah dewa.
-- c028-v007: Di dan – sekitar – tempat itu, ada tanah – kepala – pulau, bernama Poplios, yang menyambut kita hari tiga, ramah menjamu.
-- c028-v008: Terjadi dan, – bapa – Poplios, demam dan disentri menderita, berbaring, kepada siapa – Paulos, masuk dan berdoa, meletakkan – tangan kepadanya, menyembuhkan dia.
-- c028-v009: Ini dan terjadi, juga – sisanya – di – pulau memiliki penyakit datang dan disembuhkan,
-- c028-v010: yang juga banyak penghormatan menghormati kita, dan berangkat, menempatkan – untuk – kebutuhan.
-- c028-v011: Setelah dan tiga bulan, berangkat dengan kapal musim–dingin di – pulau, Alexandria, lambang Dioskouroi.
-- c028-v012: Dan berlabuh di Surakousai, tinggal hari tiga,
-- c028-v013: dari–sana melewati, tiba di Rhegion. Dan setelah satu hari, datang selatan, hari–kedua datang di Potioloi,
-- c028-v014: di–mana menemukan saudara-saudara, diminta di–antara mereka tinggal hari tujuh. Dan demikian ke – Roma datang.
-- c028-v015: Dan–dari–sana – saudara-saudara, mendengar – tentang kita, datang untuk bertemu kita sampai Appiou Forum dan Tiga Kedai; yang melihat – Paulos, bersyukur – Allah, mengambil keberanian.
-- c028-v016: Ketika dan masuk ke Roma, – perwira menyerahkan – tahanan – komandan–penjaga, diizinkan – Paulos tinggal secara– sendiri, bersama – yang–menjaga dia prajurit.
-- c028-v017: Terjadi dan, setelah hari tiga memanggil dia – yang–ada – orang–Yahudi pemimpin. Berkumpul dan mereka, berkata kepada mereka, Aku, laki-laki, saudara-saudara, tidak–ada melawan melakukan – bangsa, atau – kebiasaan – leluhur; tahanan dari Hierosoluma diserahkan ke – tangan – orang–Romawi,
-- c028-v018: yang memeriksa aku, ingin membebaskan, karena – tidak–satu alasan kematian ada dalam aku.
-- c028-v019: Menentang dan – orang–Yahudi, dipaksa naik–banding Kaisar, tidak seolah-olah – bangsa –ku memiliki sesuatu menuduh.
-- c028-v020: Karena ini maka – alasan meminta kamu, melihat dan berbicara; karena karena – pengharapan – Israēl, – rantai ini dikenakan.
-- c028-v021: – Dan kepada dia berkata, Kami tidak–juga surat tentang engkau menerima dari – Yudea, tidak–juga datang siapapun – saudara melaporkan, atau berbicara sesuatu tentang engkau jahat.
-- c028-v022: Menginginkan tetapi dari engkau mendengar yang berpikir, tentang memang karena – sekte ini, diketahui kita adalah, bahwa di–mana–pun ditentang.
-- c028-v023: Menetapkan dan kepadanya hari, datang kepada dia ke – penginapan lebih–banyak, kepada–siapa menjelaskan, bersaksi – kerajaan – Allah, meyakinkan dan mereka tentang – Yēsous, dari dan – hukum Mouss, dan – nabi-nabi, dari pagi sampai petang.
-- c028-v024: Dan – memang percaya – yang–dikatakan; – dan tidak–percaya.
-- c028-v025: Tidak–setuju dan menjadi kepada satu–sama–lain, pergi; berkata – Paulos perkataan satu bahwa: Baik – Roh – Kudus berbicara melalui Ēsaias – nabi kepada – bapa-bapa kamu,
-- c028-v026: berkata, Pergilah kepada – bangsa ini, dan katakan, Dengan–pendengaran akan–mendengar, dan tidak – mengerti; dan melihat akan–melihat, dan tidak – melihat.
-- c028-v027: Menebal karena – hati – bangsa ini, dan – telinga berat mendengar, dan – mata mereka menutup, jangan– pernah melihat – mata, dan – telinga mendengar, dan – hati mengerti, dan berbalik, dan menyembuhkan mereka.
-- c028-v028: Diketahui maka biarlah, kamu bahwa – bangsa-bangsa diutus ini – keselamatan – Allah; mereka juga akan–mendengar!
-- c028-v029: Dan ini dia berkata, pergi – orang–Yahudi, banyak memiliki di diri–sendiri perdebatan.
-- c028-v030: Tinggal dan dua–tahun penuh di sendiri sewa, dan menerima semua – yang–datang kepada dia,
-- c028-v031: memberitakan – kerajaan – Allah, dan mengajar – tentang – Tuhan Yēsous Kristos, dengan semua keberanian tanpa–halangan.

